def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import sys
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))

    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"
    memo = {}
    active = set()

    def tokenize(s):
        toks = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
                continue
            if "0" <= c <= "9":
                j = i + 1
                while j < n and "0" <= s[j] <= "9":
                    j += 1
                toks.append(("num", int(s[i:j])))
                i = j
                continue
            if "A" <= c <= "Z":
                if i + 1 < n and "0" <= s[i + 1] <= "9":
                    j = i + 2
                    while j < n and "0" <= s[j] <= "9":
                        j += 1
                    ref = s[i:j]
                    row = int(ref[1:])
                    if len(ref) > 3 or row < 1 or row > 99 or ref[1] == "0":
                        raise ValueError("bad cell")
                    toks.append(("cell", ref))
                    i = j
                    continue
                j = i + 1
                while j < n and "A" <= s[j] <= "Z":
                    j += 1
                toks.append(("name", s[i:j]))
                i = j
                continue
            two = s[i:i + 2]
            if two in ("<=", ">=", "<>"):
                toks.append(("op", two))
                i += 2
                continue
            if c in "+-*/()=,:<>":
                toks.append(("op", c))
                i += 1
                continue
            raise ValueError("bad char")
        toks.append(("eof", None))
        return toks

    def parse_formula(src):
        toks = tokenize(src)
        pos = [0]

        def peek():
            return toks[pos[0]]

        def advance():
            tok = toks[pos[0]]
            pos[0] += 1
            return tok

        def expect_op(value):
            if advance() != ("op", value):
                raise ValueError("expected " + value)

        def expect_cell():
            tok = advance()
            if tok[0] != "cell":
                raise ValueError("expected cell")
            return tok[1]

        def parse_expr():
            operands = [parse_term()]
            ops = []
            while peek() in (("op", "+"), ("op", "-")):
                ops.append(advance()[1])
                operands.append(parse_term())
            return operands[0] if not ops else ("seq", ops, operands)

        def parse_term():
            operands = [parse_unary()]
            ops = []
            while peek() in (("op", "*"), ("op", "/")):
                ops.append(advance()[1])
                operands.append(parse_unary())
            return operands[0] if not ops else ("seq", ops, operands)

        def parse_unary():
            if peek() == ("op", "-"):
                advance()
                return ("neg", parse_unary())
            return parse_atom()

        def parse_agg_arg():
            save = pos[0]
            if peek()[0] == "cell":
                first = advance()[1]
                if peek() == ("op", ":"):
                    advance()
                    return ("range", first, expect_cell())
                pos[0] = save
            return ("expr", parse_expr())

        def parse_atom():
            tok = advance()
            if tok[0] == "num":
                return ("num", tok[1])
            if tok[0] == "cell":
                return ("cell", tok[1])
            if tok == ("op", "("):
                node = parse_expr()
                expect_op(")")
                return node
            if tok[0] == "name":
                name = tok[1]
                expect_op("(")
                if name in ("SUM", "MIN", "MAX"):
                    args = [parse_agg_arg()]
                    while peek() == ("op", ","):
                        advance()
                        args.append(parse_agg_arg())
                    expect_op(")")
                    return ("call", name, args)
                if name == "IF":
                    left = parse_expr()
                    cmp_tok = advance()
                    if cmp_tok[0] != "op" or cmp_tok[1] not in ("=", "<>", "<", "<=", ">", ">="):
                        raise ValueError("bad if op")
                    right = parse_expr()
                    expect_op(",")
                    then_node = parse_expr()
                    expect_op(",")
                    else_node = parse_expr()
                    expect_op(")")
                    return ("if", left, cmp_tok[1], right, then_node, else_node)
                raise ValueError("unknown function")
            raise ValueError("bad atom")

        node = parse_expr()
        if peek()[0] != "eof":
            raise ValueError("trailing input")
        return node

    def is_err(v):
        return isinstance(v, str)

    def ref_parts(ref):
        return ord(ref[0]) - 65, int(ref[1:])

    def eval_node(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return eval_cell(node[1])
        if kind == "neg":
            v = eval_node(node[1])
            return v if is_err(v) else -v
        if kind == "seq":
            ops, operands = node[1], node[2]
            acc = eval_node(operands[0])
            for op, rhs in zip(ops, operands[1:]):
                if is_err(acc):
                    return acc
                v = eval_node(rhs)
                if is_err(v):
                    return v
                if op == "+":
                    acc = acc + v
                else:
                    if v == 0:
                        return DIV0
                    q = abs(acc) // abs(v)
                    if (acc < 0) != (v < 0):
                        q = -q
                    acc = q
            return acc
        if kind == "if":
            lv = eval_node(node[1])
            if is_err(lv):
                return lv
            rv = eval_node(node[3])
            if is_err(rv):
                return rv
            op = node[2]
            if op == "=":
                cond = lv == rv
            elif op == "<>":
                cond = lv != rv
            elif op == "<":
                cond = lv < rv
            elif op == "<=":
                cond = lv <= rv
            elif op == ">":
                cond = lv > rv
            else:
                cond = lv >= rv
            return eval_node(node[4] if cond else node[5])
        return eval_call(node[1], node[2])

    def eval_call(name, args):
        vals = []
        for arg in args:
            if arg[0] == "range":
                c1, r1 = ref_parts(arg[1])
                c2, r2 = ref_parts(arg[2])
                for r in range(min(r1, r2), max(r1, r2) + 1):
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        ref = chr(65 + c) + str(r)
                        if ref in cells:
                            v = eval_cell(ref)
                            if is_err(v):
                                return v
                            vals.append(v)
            else:
                v = eval_node(arg[1])
                if is_err(v):
                    return v
                vals.append(v)
        if name == "SUM":
            return sum(vals)
        if not vals:
            return 0
        return min(vals) if name == "MIN" else max(vals)

    def eval_cell(name):
        if name not in cells:
            return 0
        if name in memo:
            return memo[name]
        if name in active:
            return CYCLE
        active.add(name)
        try:
            text = cells[name].strip()
            if text.startswith("="):
                value = eval_node(parse_formula(text[1:]))
            else:
                value = int(text)
        finally:
            active.discard(name)
        memo[name] = value
        return value

    result = {}
    for name in cells:
        result[name] = eval_cell(name)
    return result
